from 写入第二遍 import add
add('10_001',6,'16:9，从青一侧回看武士的斜俯中近景；武士头肩前压，握柄与鞘口横越前景。相机与他平行前移，句尾快速收紧到双手与狭窄眼缝。','武士追进时将刀鞘带到身前，左手稳住鞘口，右手覆上缠柄；头压低而眼睛仍盯着画外前方的青。说话时手指逐一扣紧，右肩在外衣下向后收，右肘再骤然外拉，刀根从鞘口露出一线冷亮，外衣向后展开。','右后方铅蓝天空被短密斜线压成方向明确的速度底场，近处屋顶只在下缘掠过一角。','破烟囱后方的开阔天空从武士侧后给冷白柔光，鞘口短暂闪出金属反光。','风声压低，指节握柄与鞘口轻碰，句尾接紧绷的拔刀金属擦音。',japanese=['今は、のんびり対策を考えている暇などないぞ。'],tone='气息稳定、催逼而从容；句尾与出鞘起动相接。',phase='preparation',kind='mixed',node={'武士.刀':'右手拔刀中、左手持鞘','武士.阶段':'追击中起斩'},pcard={'opening':'武士已追近，头肩低而手有余裕。','beats':['逐指握紧，视线锁住青','句尾右肩收后，拔刀骤然起动'],'coupling':'用从容发声压住突然的出刀速度。','landing':'刀锋即将横扫，追击没有停住。'})
add('10_002',1,'16:9，倾斜的双眼大特写，前景浅色弧面占下半幅，只留青两只眼睛与刘海；固定机位，刀光从下缘短促擦过。','青的眼睛先追住逼近的画外刀口，瞳孔骤然收紧；她把下颌向后带，眉间压出明确折线，眼睛仍留在刀路上，刘海被迎面的气流掀开一线。','主体几乎占满画幅，仅上侧狭窄空隙为浅冷灰天空。','上方冷白天光压出眼睛高光；掠过刀面的反光在下缘一闪而止。','金属擦音接一记骤短破风，吸气声被风压截住。',phase='reaction',node={'青.阶段':'发现刀路开始后仰'},pcard={'opening':'视线先于身体接住威胁。','beats':['盯住刀路，瞳孔缩紧','下颌后带，开始避让'],'coupling':'这次注意变化直接触发后仰，不是无意义眨眼。','landing':'头已开始离开原攻击线。'},background_mode='occluded')
add('10_003',2.5,'16:9，近大远小的倒悬中景，青的倒置头胸在近侧，武士在上方远处。镜头沿青腰背的后翻弧线下摇，落在她头朝下、胸腹拱起、武士刀路从她上方通过的关系构图。','青把胸腰向后折开，头先越过身体下方，屈腿跟着翻起；她睁圆眼张口惊叫，双臂分开调整后翻，长发甩成两道弧带。武士挥出的刀从她刚离开的高度横穿，刀口掠过她上方后继续向她身后的烟囱方向扫去。','浅冷白天空占大部，左右边缘是疾掠的屋檐暗形与同向弧线，尚未展示烟囱被切断的结果。','两人上方天空冷白漫射；刀锋掠过时有短促白亮高光。','一记长弧破风紧贴近侧经过，青的惊叫短促，发束与衣摆被气流拉响。',japanese=['ああっ！！'],tone='被逼出的短促惊叫，接一口急气。',phase='process',kind='mixed',node={'青.阶段':'空中后翻避开斩击','武士.刀':'右手已出鞘横斩'},pcard={'opening':'青已经开始后仰，眼睛追着刀路。','beats':['头胸后折、腿随腰越过','倒悬惊叫，刀路从上方穿过'],'coupling':'避让与挥刀同时发生，刀势继续向烟囱。','landing':'青未被刀命中，仍在后翻。'})
